import Foundation

// Cloud Infrastructure SDK - Service Mesh Controller
// Circuit Breaker with Role-Based Access Control

enum ServiceRole: Int, Comparable {
    case viewer = 0
    case operator_ = 1
    case admin = 2
    case superAdmin = 3

    static func < (lhs: ServiceRole, rhs: ServiceRole) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct ServiceIdentity {
    let principalId: String
    let role: ServiceRole
    let tenantId: String
    let delegatedFrom: ServiceIdentity?

    var effectiveRole: ServiceRole {
        // Delegation chain: effective role is the minimum of delegator and delegatee
        if let delegator = delegatedFrom {
            return min(self.role, delegator.effectiveRole)
        }
        return self.role
    }
}

enum CircuitState {
    case closed
    case open
    case halfOpen
}

class CircuitBreaker {
    private var state: CircuitState = .closed
    private var failureCount: Int = 0
    private let failureThreshold: Int = 5
    private var lastFailureTime: Date?
    private let recoveryTimeout: TimeInterval = 30.0

    var isAvailable: Bool {
        switch state {
        case .closed:
            return true
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) > recoveryTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }

    func recordSuccess() {
        state = .closed
        failureCount = 0
    }

    func recordFailure() {
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= failureThreshold {
            state = .open
        }
    }
}

struct AuthorizationPolicy {
    let requiredRole: ServiceRole
    let resource: String
    let allowDelegation: Bool

    func evaluate(identity: ServiceIdentity) -> Bool {
        let roleToCheck = allowDelegation ? identity.effectiveRole : identity.role
        return roleToCheck >= requiredRole
    }
}

class InfrastructureController {
    private let circuitBreaker = CircuitBreaker()
    private var authzCache: [String: (result: Bool, timestamp: Date)] = [:]
    private let cacheTTL: TimeInterval = 300.0

    private let policies: [String: AuthorizationPolicy] = [
        "cluster.scale": AuthorizationPolicy(requiredRole: .admin, resource: "cluster.scale", allowDelegation: true),
        "cluster.read": AuthorizationPolicy(requiredRole: .viewer, resource: "cluster.read", allowDelegation: true),
        "cluster.delete": AuthorizationPolicy(requiredRole: .superAdmin, resource: "cluster.delete", allowDelegation: false),
        "node.drain": AuthorizationPolicy(requiredRole: .admin, resource: "node.drain", allowDelegation: true),
        "config.update": AuthorizationPolicy(requiredRole: .operator_, resource: "config.update", allowDelegation: true)
    ]

    private func cacheKey(identity: ServiceIdentity, resource: String) -> String {
        // Include tenantId to prevent cross-tenant reuse of authorization results
        // when principal IDs collide or are reused across tenants.
        return "\(identity.tenantId):\(identity.principalId):\(resource)"
    }

    private func checkAuthzWithCache(identity: ServiceIdentity, resource: String) -> Bool {
        let key = cacheKey(identity: identity, resource: resource)

        if let cached = authzCache[key] {
            if Date().timeIntervalSince(cached.timestamp) < cacheTTL {
                return cached.result
            }
            authzCache.removeValue(forKey: key)
        }

        guard let policy = policies[resource] else {
            return false
        }

        let result = policy.evaluate(identity: identity)
        authzCache[key] = (result: result, timestamp: Date())
        return result
    }

    func executeOperation(identity: ServiceIdentity, resource: String, operation: () -> Result<String, Error>) -> Result<String, Error> {
        // Circuit breaker check
        guard circuitBreaker.isAvailable else {
            return .failure(NSError(domain: "CircuitOpen", code: 503, userInfo: [NSLocalizedDescriptionKey: "Service unavailable - circuit breaker open"]))
        }

        // Authorization check with fallback behavior during circuit breaker half-open state
        let authorized: Bool
        if circuitBreaker.isAvailable {
            authorized = checkAuthzWithCache(identity: identity, resource: resource)
        } else {
            // Fallback: deny all during outage
            authorized = false
        }

        guard authorized else {
            return .failure(NSError(domain: "AuthzDenied", code: 403, userInfo: [NSLocalizedDescriptionKey: "Insufficient permissions for \(resource)"]))
        }

        let result = operation()
        switch result {
        case .success:
            circuitBreaker.recordSuccess()
        case .failure:
            circuitBreaker.recordFailure()
        }

        return result
    }

    // Batch operation with per-operation authorization
    func executeBatchOperations(identity: ServiceIdentity, operations: [(resource: String, op: () -> Result<String, Error>)]) -> [Result<String, Error>] {
        var results: [Result<String, Error>] = []

        for (_, operation) in operations.enumerated() {
            // Each operation in the batch must be independently authorized
            // No cross-operation authorization propagation
            let result = executeOperation(identity: identity, resource: operation.resource, operation: operation.op)
            results.append(result)
        }

        return results
    }
}

// Usage example
let viewer = ServiceIdentity(principalId: "svc-001", role: .viewer, tenantId: "tenant-a", delegatedFrom: nil)
let controller = InfrastructureController()

let readResult = controller.executeOperation(identity: viewer, resource: "cluster.read") {
    return .success("cluster data")
}
print("Read result: \(readResult)")
